{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Not Enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server access logging enabled, which is required for auditing and security monitoring of data access."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Disabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "LOW",
      "explanation": "Versioning is not enabled on the bucket. While often acceptable for transient logs, enabling versioning provides protection against accidental deletion or overwrites."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 Bucket Encryption Not Configured",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "Server-side encryption is not explicitly configured. Data at rest should be encrypted to meet security compliance standards."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_versioning" "flowbucket_versioning" {
  bucket = aws_s3_bucket.flowbucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flowbucket_encryption" {
  bucket = aws_s3_bucket.flowbucket.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_logging" "flowbucket_logging" {
  bucket = aws_s3_bucket.flowbucket.id
  target_bucket = aws_s3_bucket.flowbucket.id # In production, this should point to a separate secure log bucket
  target_prefix = "log/"
}",
  "fix_summary": "Added resources to enable versioning, configure server-side encryption (AES256), and enable access logging for the S3 bucket. Note: The logging configuration currently targets the same bucket for simplicity; in a production environment, this should target a dedicated, secured log storage bucket."
}
